import argparse
from operations import Calculator

def main():
    parser = argparse.ArgumentParser(description="CLI Calculator")
    parser.add_argument("--op", choices=[
        'add', 'subtract', 'multiply', 'divide', 'power', 'modulo', 
        'memory_store', 'memory_recall', 'memory_clear', 
        'get_history', 'clear_history', 'evaluate'
    ], required=True)
    parser.add_argument("a", type=float, nargs='?', help="First operand or value to store")
    parser.add_argument("b", type=float, nargs='?', help="Second operand")
    parser.add_argument("--expr", type=str, help="Expression for evaluate operation")

    args = parser.parse_args()
    calc = Calculator()

    try:
        if args.op == 'evaluate':
            if not args.expr:
                print("Error: --expr is required for evaluate operation.")
                return
            result = calc.evaluate(args.expr)
            print(f"Result: {result}")

        elif args.op in ['add', 'subtract', 'multiply', 'divide', 'power', 'modulo']:
            if args.a is None or args.b is None:
                print(f"Error: {args.op} requires two numeric arguments.")
                return
            func = getattr(calc, args.op)
            result = func(args.a, args.b)
            print(f"Result: {result}")

        elif args.op == 'memory_store':
            if args.a is None:
                print("Error: memory_store requires a numeric value.")
                return
            calc.memory_store(args.a)
            print("Value stored in memory.")

        elif args.op == 'memory_recall':
            print(f"Memory: {calc.memory_recall()}")

        elif args.op == 'memory_clear':
            calc.memory_clear()
            print("Memory cleared.")

        elif args.op == 'get_history':
            print(f"History: {calc.get_history()}")

        elif args.op == 'clear_history':
            calc.clear_history()
            print("History cleared.")

    except ValueError as e:
        print(f"Error: {e}")
    except TypeError as e:
        print(f"Type Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

