from typing import List, NamedTuple, Optional, Union

class HistoryEntry(NamedTuple):
    """Represents a single arithmetic operation in the calculator history."""
    operation: str
    a: float
    b: float
    result: float

class Calculator:
    def __init__(self) -> None:
        """Initializes the calculator with an empty history."""
        self._history: List[HistoryEntry] = []

    def _record(self, op: str, a: float, b: float, res: float) -> None:
        """Records an arithmetic operation in history."""
        self._history.append(HistoryEntry(float(a), float(b), op, float(res)))

    def add(self, a: float, b: float) -> float:
        res: float = float(a) + float(b)
        self._record("add", a, b, res)
        return res

    def subtract(self, a: float, b: float) -> float:
        res: float = float(a) - float(b)
        self._record("subtract", a, b, res)
        return res

    def multiply(self, a: float, b: float) -> float:
        res: float = float(a) * float(b)
        self._record("multiply", a, b, res)
        return res

    def divide(self, a: float, b: float) -> float:
        if float(b) == 0:
            raise ValueError("Cannot divide by zero.")
        res: float = float(a) / float(b)
        self._record("divide", a, b, res)
        return res

    def power(self, base: float, exponent: float) -> float:
        try:
            res: float = float(pow(base, exponent))
        except (OverflowError, ZeroDivisionError, ValueError) as e:
            raise ValueError(f"Invalid power operation: {e}")
        self._record("power", base, exponent, res)
        return res

    def modulo(self, a: float, b: float) -> float:
        if float(b) == 0:
            raise ValueError("Cannot perform modulo by zero.")
        res: float = float(a) % float(b)
        self._record("modulo", a, b, res)
        return res

    def get_history(self) -> List[HistoryEntry]:
        """Returns a copy of the operation history."""
        return self._history.copy()

    def clear_history(self) -> None:
        """Clears all entries from history."""
        self._history = []

    def evaluate(self, expression: str) -> float:
        """
        Parses and evaluates a mathematical string expression.

        Args:
            expression: The string to evaluate (e.g., "5 + 3 * 2").
        """
        try:
            tree = ast.parse(expression, mode='eval')
            return self._recursive_eval(tree.body)
        except Exception as e:
            raise ValueError(f"Invalid expression: {e}")

    def _recursive_eval(self, node: ast.AST) -> float:
        if isinstance(node, ast.Constant):
            return float(node.value)
        elif isinstance(node, ast.UnaryOp):
            val = self._recursive_eval(node.operand)
            if isinstance(node.op, ast.USub): return -val
            if isinstance(node.op, ast.UAdd): return val
        elif isinstance(node, ast.BinOp):
            left = self._recursive_eval(node.left)
            right = self._recursive_eval(node.right)
            if isinstance(node.op, ast.Add): return left + right
            if isinstance(node.op, ast.Sub): return left - right
            if isinstance(node.op, ast.Mult): return left * right
            if isinstance(node.op, ast.Div):
                if right == 0: raise ValueError("Division by zero")
                return left / right
            if isinstance(node.op, ast.Pow): return pow(left, right)
            if isinstance(node.op, ast.Mod):
                if right == 0: raise ValueError("Modulo by zero")
                return left % right
        raise TypeError(f"Unsupported expression component: {type(node).__name__}")

